function printFrame(){const f=$('#d10-frame');if(!f)return;const go=()=>{try{f.contentWindow.focus();f.contentWindow.print()}catch(e){window.open(f.src,'_blank')}};if(f.contentDocument&&f.contentDocument.readyState==='complete')go();else f.addEventListener('load',go,{once:true})}
