 const st=c?`<p class="r9-meta">${chip(c)}${c.code?'<span class="code">'+c.code+'</span>':''}<span class="t2">${c.run.st==='done'?'Не покупать сейчас — нужны данные · '+NODOC.toLowerCase():c.run.st==='input'?'вопрос к вам: '+esc((P9().DEMO.q[sk]||{}).q||''):'ждём внешний ответ'}</span></p>`:'<p>Исследование не запускалось.</p>';
